"""Every picture on the site, from the owner's two photos. Nothing here is generated by a model and no credit is spent.
Run from the build folder with the backend python: python gen/assets.py

The board photo's ground is plain dark stone, so its extension to the screen's shape (rules 3c.12) is made from its own
pixels: each new row or column takes the photo's edge colour, plus the stone grain from the empty top band of the photo.
The original pixels are pasted back untouched. Compared at full size beside the photo: gen/ext-check.jpg."""
import numpy as np
from PIL import Image, ImageDraw, ImageFilter

BOARD = Image.open('src/owner/p02.jpg').convert('RGB')
FLYER = Image.open('src/owner/p01.jpg').convert('RGB')
W, H = BOARD.size
rng = np.random.default_rng(7)


def grain(h, w):
    """Stone grain: the high-pass of the photo's empty top band, mirrored and tiled, so it is the same stone."""
    band = np.asarray(BOARD.crop((0, 0, W, 240))).astype(np.float32)
    low = np.asarray(BOARD.crop((0, 0, W, 240)).filter(ImageFilter.GaussianBlur(40))).astype(np.float32)
    hi = band - low
    tile = np.concatenate([hi, hi[::-1]], axis=0)
    tile = np.concatenate([tile, tile[:, ::-1]], axis=1)
    ty, tx = np.tile(tile, (h // tile.shape[0] + 2, w // tile.shape[1] + 2, 1)).shape[:2]
    big = np.tile(tile, (h // tile.shape[0] + 2, w // tile.shape[1] + 2, 1))
    y0, x0 = rng.integers(0, ty - h), rng.integers(0, tx - w)
    return big[y0:y0 + h, x0:x0 + w]


def extend(cw, ch, px, py):
    """A canvas cw x ch with the photo at (px, py); the rest continues its edges, with the feather inside the new part."""
    a = np.asarray(BOARD).astype(np.float32)
    soft = np.asarray(BOARD.filter(ImageFilter.GaussianBlur(70))).astype(np.float32)
    ys = np.clip(np.arange(ch) - py, 0, H - 1)
    xs = np.clip(np.arange(cw) - px, 0, W - 1)
    base = soft[np.ix_(ys, xs)]
    # below the photo the floor falls towards the dark of the stone rather than holding a band of reflection
    under = np.clip((np.arange(ch) - (py + H)) / 500, 0, 1)[:, None, None]
    dark = np.median(a[:200].reshape(-1, 3), axis=0) * .55
    base = base * (1 - under) + dark * under
    out = base + grain(ch, cw) * (1 - .75 * under)
    # paste back, feathering only over the outermost 60 px of the photo where it meets a new side
    m = np.ones((H, W), np.float32)
    f = 60
    if px > 0:
        m[:, :f] = np.minimum(m[:, :f], np.linspace(0, 1, f))
    if px + W < cw:
        m[:, -f:] = np.minimum(m[:, -f:], np.linspace(1, 0, f))
    if py > 0:
        m[:f, :] = np.minimum(m[:f, :], np.linspace(0, 1, f)[:, None])
    if py + H < ch:
        m[-f:, :] = np.minimum(m[-f:, :], np.linspace(1, 0, f)[:, None])
    m = m[..., None]
    out[py:py + H, px:px + W] = a * m + out[py:py + H, px:px + W] * (1 - m)
    return Image.fromarray(np.clip(out, 0, 255).astype(np.uint8))


# laptop: the photo at the right, words in the new stone at the left. phone: the photo near the top, words below it.
wide = extend(4000, 2250, 1700, 225)
tall = extend(2250, 5000, 0, 330)
wide.resize((3200, 1800), Image.LANCZOS).save('assets/board-wide.webp', quality=82, method=6)
tall.resize((1400, 3111), Image.LANCZOS).save('assets/board-tall.webp', quality=82, method=6)

# the whole board, for the product card and the Shop stage (their photo, whole)
BOARD.resize((1400, 1120), Image.LANCZOS).save('assets/board.webp', quality=84, method=6)
# the share picture, 1200x630
wide.resize((1200, 675), Image.LANCZOS).crop((0, 22, 1200, 652)).save('assets/og.webp', quality=86, method=6)

# their photos on wood, cut from the flyer where it has no words: the basket with the sauce jars, the strips with lemon
FLYER.crop((452, 790, 1132, 1300)).save('assets/basket.webp', quality=90, method=6)
FLYER.crop((0, 985, 640, 1365)).save('assets/strips.webp', quality=90, method=6)


def disc(box, out, size):
    im = BOARD.crop(box).resize((size * 2, size * 2), Image.LANCZOS)
    mask = Image.new('L', (size * 8, size * 8), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size * 8 - 1, size * 8 - 1), fill=255)
    im.putalpha(mask.resize((size * 2, size * 2), Image.LANCZOS))
    im.save(out, quality=90, method=6)


# the logo, from the lid of a sauce cup: centre and radius measured on the photo
disc((1150, 673, 1340, 863), 'assets/logo.webp', 56)
# the three sauce cups, whole, for the order steps
disc((800, 636, 1084, 920), 'assets/cup-a.webp', 40)
disc((1104, 636, 1396, 928), 'assets/cup-b.webp', 40)
disc((944, 882, 1236, 1174), 'assets/cup-c.webp', 40)

# the kashrut seal on the flyer, as printed
seal = FLYER.crop((66, 1376, 192, 1502))
seal.save('assets/seal.webp', quality=92, method=6)

# to look at: the seam at full size, beside the photo
check = Image.new('RGB', (1800, 1000), 'black')
check.paste(wide.crop((1100, 0, 2000, 1000)), (0, 0))
check.paste(tall.crop((0, 1700, 900, 2700)), (900, 0))
check.save('gen/ext-check.jpg', quality=88)
for n in ('board-wide', 'board-tall', 'board', 'og', 'basket', 'strips', 'logo', 'cup-a', 'cup-b', 'cup-c', 'seal'):
    im = Image.open(f'assets/{n}.webp')
    print(n, im.size)
